def decide(observation, tools):
    match_scores = tools.match()
    frame = 1 if match_scores[1] > match_scores[0] else 0
    view = observation["views"][frame]
    heading = view["heading"]
    locate_result = tools.locate()
    point_result = tools.point()
    if locate_result[0] > 0 or point_result[0] is not None:
        return frame, "right" if heading > 0 else "left", {"heading": heading}
    return frame, "right", {"heading": heading}

